import { useState } from "react";
import axios from "axios";

export default function Cadastrar() {
  const [formData, setFormData] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
  });

  const [imagem, setImagem] = useState(null);
  const [mensagem, setMensagem] = useState("");

  function handleChange(e) {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  }

  function handleFileChange(e) {
    setImagem(e.target.files[0]);
  }

  async function handleSubmit(e) {
    e.preventDefault();

    if (!imagem) {
      return setMensagem("Por favor, selecione uma imagem.");
    }

    const data = new FormData();
    for (const key in formData) {
      data.append(key, formData[key]);
    }
    data.append("foto", imagem);

    try {
      await axios.post("http://localhost:3001/usuarios", data, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      setMensagem("Usuário cadastrado com sucesso!");
    } catch (erro) {
      console.error(erro);
      setMensagem("Erro ao cadastrar usuário.");
    }
  }

  return (
    <div>
      <h2>Cadastrar Usuário</h2>
      <form onSubmit={handleSubmit}>
        <input name="nome" placeholder="Nome" onChange={handleChange} />
        <input name="idade" placeholder="Idade" onChange={handleChange} />
        <input name="rua" placeholder="Rua" onChange={handleChange} />
        <input name="bairro" placeholder="Bairro" onChange={handleChange} />
        <input name="estado" placeholder="Estado" onChange={handleChange} />
        <textarea name="biografia" placeholder="Biografia" onChange={handleChange} />

        <input type="file" accept="image/*" onChange={handleFileChange} />

        <button type="submit">Cadastrar</button>
      </form>

      {mensagem && <p>{mensagem}</p>}
    </div>
  );
}
